mapper.select:
SELECT 
  FROM emp19_education
  JOIN emp01_person ON emp19_person_id = emp01_person_id
 WHERE emp19_person_id  = #{personId}
   AND emp01_company_id = #{companyId}

mapper.update:
UPDATE emp19_education
   SET emp19_issue_date   = #{req.issueDate}::date
     , emp19_content      = #{req.content}
     , emp19_education_yn = #{req.educationYn}
 WHERE emp19_education_id = #{educationId}
   AND emp19_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

mapper.delete:
DELETE FROM emp19_education
 WHERE emp19_education_id IN
#{id}
   AND emp19_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

mapper.insert:
INSERT INTO emp19_education
       ( emp19_education_id, emp19_person_id, emp19_issue_date, emp19_content
       , emp19_education_yn, emp19_note, emp19_education_corp_nm )
SELECT #{newId}, p.emp01_person_id, e.emp19_issue_date, e.emp19_content
     , e.emp19_education_yn, e.emp19_note, e.emp19_education_corp_nm
  FROM emp19_education e
  JOIN emp01_person s ON s.emp01_person_id = e.emp19_person_id AND s.emp01_company_id = #{companyId}
  JOIN emp01_person p ON p.emp01_person_id = #{personId} AND p.emp01_company_id = #{companyId}
 WHERE e.emp19_education_id = #{educationId}
